function commit(change){if(storageError){toast(storageError);return false}try{const next=JSON.parse(JSON.stringify(data));change(next);localStorage.setItem(STORAGE_KEY,JSON.stringify(next));data=next;return true}catch(e){toast('保存失败：浏览器存储不可用或空间不足，请保留现有数据');return false}}
function nowText(){return new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai'});}
function prevDate(date,days=1){const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-days);return d.toISOString().slice(0,10)}
function usage(d,date=state.date){if(d.added)return d.type==='water'?{total:0}:{peak:0,valley:0,total:0};const day=Math.round((Date.parse(date+'T00:00:00Z')-Date.parse('2026-09-01T00:00:00Z'))/86400000),weekday=[.92,1.05,.98,1.12,.96,.89,1.02][((day%7)+7)%7],f=(.86+((d.index*7+day*13)%37)/100)*weekday;if(d.type==='water')return{total:round((1.2+(d.index%19)*.27)*f)};const peak=round((18+(d.index%35)*1.51)*f),valley=round((10+(d.index%23)*.91)*f);return{peak,valley,total:round(peak+valley)}}
const readingCache=new Map();
function reading(d,date=state.date){const key=d.id+':'+date+':'+d.readBase;if(readingCache.has(key))return readingCache.get(key);const day=Math.round((Date.parse(date+'T00:00:00Z')-Date.parse('2026-09-01T00:00:00Z'))/86400000);let value=d.readBase;for(let i=0;i<=day;i++)value+=usage(d,prevDate('2026-09-01',-i)).total;value=round(value);readingCache.set(key,value);return value}
function pool(type=state.type,building=state.building){return devices.filter(d=>d.type===type&&(building==='全部位置'||(roomFor(d.id)?.building||d.building)===building))}
function totals(type,date=state.date,building=state.building){return pool(type,building).reduce((s,d)=>{const u=usage(d,date);s.total+=u.total;s.peak+=u.peak||0;s.valley+=u.valley||0;return s},{total:0,peak:0,valley:0})}
function filtered(){const q=state.search.trim().toLowerCase();return pool().filter(d=>(!q||[d.id,d.name,deviceDisplayName(d),d.address,devicePosition(d)].some(x=>String(x).toLowerCase().includes(q)))&&(state.status==='all'||(state.status==='online')===d.online))}
