let modalKeyHandler=null;
function modal(title,body,footer='',wide=false){const previous=document.activeElement;if(modalKeyHandler)document.removeEventListener('keydown',modalKeyHandler);$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" aria-label="关闭">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;const close=()=>{document.removeEventListener('keydown',modalKeyHandler);$('#modal-root').innerHTML='';previous?.isConnected&&previous.focus()};$('.close').onclick=close;$('.modal-overlay').onclick=e=>{if(e.target===e.currentTarget)close()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);modalKeyHandler=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=[...$('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(n=>!n.closest('[hidden]'));if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',modalKeyHandler);$('.close').focus()}
