function stat(label,value,unit,icon,tone,foot){return `<div class="summary-card"><div class="summary-top">${label}<span class="stat-icon ${tone}">${ico(icon)}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div><svg class="stat-spark" viewBox="0 0 70 28"><path d="m0 25 9-5 8 3 9-12 8 4 9-9 9 3 9-7" stroke="${tone==='teal'?'#15af9b':tone==='orange'?'#e9a04d':tone==='purple'?'#8b6fe8':'#386cf6'}" stroke-width="1.7" fill="none"/></svg></div>`}
function lineChart(type='electric',device=null){const dates=Array.from({length:7},(_,i)=>prevDate(state.date,6-i)),values=dates.map(date=>device?usage(device,date):totals(type,date));const series=type==='electric'?[['peak','#477cf5','峰时'],['valley','#19b29c','谷时']]:[['total','#19b29c','用水量']];const max=Math.max(1,...values.flatMap(v=>series.map(([k])=>v[k])))*1.2;const x=i=>57+i*90,y=v=>156-v/max*129;return `<svg viewBox="0 0 640 195" role="img" aria-label="最近七天${type==='electric'?'峰谷用电':'用水'}趋势">${Array.from({length:5},(_,i)=>`<path d="M57 ${27+i*32.25}H610" class="chart-grid"/><text x="47" y="${31+i*32.25}" text-anchor="end" class="chart-axis">${fmt(max*(4-i)/4,0)}</text>`).join('')}${series.map(([k,c,label])=>`<polyline points="${values.map((v,i)=>`${x(i)},${y(v[k])}`).join(' ')}" fill="none" stroke="${c}" stroke-width="2.7" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v[k])}" r="3.3" fill="white" stroke="${c}" stroke-width="1.8"><title>${dates[i]} ${label} ${fmt(v[k])}</title></circle>`).join('')}`).join('')}${dates.map((date,i)=>`<text class="chart-axis" x="${x(i)}" y="183" text-anchor="middle">${date.slice(5).replace('-','/')}</text>`).join('')}</svg>`}
function dashboardPage(){const e=totals('electric'),w=totals('water'),online=devices.filter(d=>d.online).length,pct=e.peak/e.total*100;return header('数据看板','从采集到用量，掌握园区每一度电、每一方水。',dateControl()+btn('导出日报','data-action="export-dashboard"',false,'download'),'ENERGY OVERVIEW')+
 `<div class="summary-grid">${stat('日用电量',fmt(e.total),'kWh','bolt','',`峰时 ${fmt(e.peak,0)} · 谷时 ${fmt(e.valley,0)}`)}${stat('日用水量',fmt(w.total),'m³','drop','teal',`${state.date} · 有效水量记录`)}${stat('设备在线率',fmt(online/devices.length*100,1),'%','device','purple',`${fmt(online,0)} / ${fmt(devices.length,0)} 台设备在线`)}${stat('最近电表批次成功率',fmt(data.plans[0].success/Math.max(1,data.plans[0].total)*100,1),'%','check','orange',`成功 ${fmt(data.plans[0].success,0)} / 应采 ${fmt(data.plans[0].total,0)} 台`)}</div>`+
 `<div class="dashboard-main"><section class="panel"><div class="panel-head"><div><div class="panel-title">用量趋势</div><div class="panel-subtitle">最近7天 · ${state.type==='electric'?'峰谷用电对比':'每日用水量'}</div></div><div class="segmented"><button data-chart-type="electric" class="${state.type==='electric'?'selected':''}">用电</button><button data-chart-type="water" class="${state.type==='water'?'selected':''}">用水</button></div></div><div class="chart-meta"><span>单位：${state.type==='electric'?'kWh':'m³'}</span><div class="legend blue-teal">${state.type==='electric'?'<span><i></i>峰时</span><span><i class="teal"></i>谷时</span>':'<span><i class="teal"></i>日用水量</span>'}</div></div><div class="trend-chart">${lineChart(state.type)}</div><div class="chart-caption"><span>已完成自然日 · 演示数据</span><b>${prevDate(state.date,6)} — ${state.date}</b></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">峰谷用电占比</div><div class="panel-subtitle">${state.date} · 全部园区</div></div>${badge('两时段','blue')}</div><div class="period-content"><div class="donut" style="background:conic-gradient(#477cf5 0 ${pct}%,#19b29c ${pct}% 100%)"><div class="donut-center">总用电量<b>${fmt(e.total,0)}</b>kWh</div></div><div class="period-legend"><div class="period-row"><i style="background:#477cf5"></i>峰时<strong>${fmt(pct,1)}%</strong></div><div class="period-row"><i style="background:#19b29c"></i>谷时<strong>${fmt(100-pct,1)}%</strong></div></div></div><div class="period-note">${ico('clock')}峰时 08:00–21:00<br>谷时 00:00–08:00、21:00–24:00</div></section></div>`+
 `<div class="dashboard-bottom"><section class="panel"><div class="panel-head"><div><div class="panel-title">最近采集与控制</div><div class="panel-subtitle">定时采集与后台操作统一记录</div></div><button class="text-button" data-nav="tasks">查看全部</button></div><div class="table-wrap"><table class="compact"><thead><tr><th>设备编号</th><th>操作</th><th>来源</th><th>结果</th></tr></thead><tbody>${data.tasks.slice(0,5).map(t=>`<tr><td><button class="text-button mono" data-task-detail="${t.id}">${t.deviceId}</button></td><td>${taskOperationName(t)}</td><td>${t.source}</td><td>${taskBadge(t.status)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">待处理事项</div><div class="panel-subtitle">及时发现采集缺失与设备异常</div></div><button class="text-button" data-nav="alarms">告警中心</button></div><div class="panel-body">${data.alarms.filter(a=>a.status==='open').slice(0,3).map(a=>`<div class="quick-link-row"><span class="stat-icon ${a.level==='info'?'':'orange'}">${ico(a.level==='info'?'info':'bell')}</span><div><b>${a.title}</b><small>${a.deviceId} · ${a.at.slice(11)}</small></div><button class="text-button" data-alarm-detail="${a.id}">处理</button></div>`).join('')||'<div class="empty">暂无待处理告警</div>'}</div></section></div>`}
function devicePage(){const e=state.type==='electric',list=pool(),on=list.filter(d=>d.online).length;return header(e?'电表台账':'水表台账',e?'管理设备档案、查看累计电量，按需发起抄表与通断电。':'管理远传水表，查看累计水量、每日用水量和在线状态。',btn('新增设备','data-action="add-device"',true,'plus'),'DEVICE MANAGEMENT')+`<div class="list-stats"><div class="list-stat"><span>设备总数</span><b>${fmt(list.length,0)}</b><small>台</small></div><div class="list-stat"><span>在线设备</span><b class="teal-text">${fmt(on,0)}</b><small>台</small></div><div class="list-stat"><span>离线设备</span><b>${fmt(list.length-on,0)}</b><small>台</small></div><div class="list-stat"><span>采集频率</span><b style="font-size:18px">${e?'每30分钟':'每天00:00'}</b></div></div><section class="panel"><div class="toolbar">${filters(true)}${btn('导出档案','data-action="export-devices"',false,'download')}</div><div id="table-area">${deviceTable()}</div></section>`}
function deviceTable(){const list=filtered(),rows=pageRows(list),e=state.type==='electric';return `<div class="table-wrap"><table><thead><tr><th>设备 / 编号</th><th>安装位置</th><th>通信地址</th><th>累计${e?'电量 (kWh)':'水量 (m³)'}</th><th>在线状态</th>${e?'<th>供电状态</th>':''}<th>操作</th></tr></thead><tbody>${rows.map(d=>{const room=roomFor(d.id);return `<tr><td>${deviceCell(d)}</td><td>${esc(devicePosition(d))}</td><td class="mono">${d.address}</td><td class="number">${fmt(reading(d))}<span class="subtext">${d.online?TODAY+' 10:00:02':LAST_DAY+' 18:00:00'}</span></td><td>${status(d)}</td>${e?`<td>${badge(d.power==='off'?'已断电':'已通电',d.power==='off'?'warn':'')}</td>`:''}<td><div class="inline-actions"><button class="text-button" data-device-detail="${d.id}">详情</button><button class="text-button" data-poll="${d.id}">抄表</button><button class="text-button" data-edit-device="${d.id}">编辑</button></div></td></tr>`}).join('')||`<tr><td colspan="${e?7:6}" class="empty">没有匹配的设备，请调整搜索或筛选条件</td></tr>`}</tbody></table></div>${pager(list.length)}`}

function usagePage(){const e=state.type==='electric',t=totals(state.type);return header('用量统计','从累计读数计算用量，按自然日查看峰谷与用水明细。',dateControl()+btn('导出明细','data-action="export-usage"',false,'download'),'CONSUMPTION ANALYTICS')+`<div class="section-tabs"><button data-usage-type="electric" class="${e?'selected':''}">电量统计</button><button data-usage-type="water" class="${!e?'selected':''}">水量统计</button></div><div class="summary-grid ${e?'':'water-summary'}">${e?stat('日总用电量',fmt(t.total),'kWh','bolt','','完整自然日累计差')+stat('峰时用电量',fmt(t.peak),'kWh','clock','','08:00–21:00')+stat('谷时用电量',fmt(t.valley),'kWh','clock','teal','00:00–08:00、21:00–24:00')+stat('电表采集频率','30','分钟','check','purple','每天48次 · 午夜边界共享'):stat('日总用水量',fmt(t.total),'m³','drop','teal','24:00与00:00累计读数之差')+stat('参与汇总',fmt(pool().length,0),'台','check','','水表数量')+stat('水表采集频率','1','次/日','clock','purple','每天00:00')}</div><section class="panel"><div class="toolbar">${filters()}${badge(e?'峰 08:00–21:00 · 谷 00:00–08:00、21:00–24:00':'每日用水 · m³',e?'blue':'')}</div><div id="table-area">${usageTable()}</div></section><div class="note-bar soft" style="margin-top:18px">${ico('info')}${e?'点击明细查看48个半小时区间。中间采样点缺失时，日峰谷边界完整仍可计算日用量；缺失区间显示“—”。':'每天00:00主动采集一次。日用水量按00:00与24:00累计读数之差计算，日末读数与下一天日初共用同一次采集。'}</div>`}
function usageTable(){const e=state.type==='electric',list=filtered();return `<div class="table-wrap"><table><thead><tr><th>设备 / 编号</th><th>房间 / 位置</th>${e?'<th>峰时用电 (kWh)</th><th>谷时用电 (kWh)</th><th>日用电量 (kWh)</th>':'<th>日初读数 (m³)</th><th>日末读数 (m³)</th><th>日用水量 (m³)</th>'}<th>数据质量</th><th>操作</th></tr></thead><tbody>${pageRows(list).map(d=>{const u=usage(d),end=reading(d),r=roomFor(d.id);return `<tr><td>${deviceCell(d)}</td><td>${r?esc(roomLabel(r)):'未关联房间'}<span class="subtext">${r?'已关联房间':'未关联房间'}</span></td>${e?`<td class="number">${fmt(u.peak)}</td><td class="number teal-text">${fmt(u.valley)}</td><td class="number blue-text">${fmt(u.total)}</td>`:`<td class="number">${fmt(end-u.total)}</td><td class="number">${fmt(end)}</td><td class="number teal-text">${fmt(u.total)}</td>`}<td>${d.index%41===3&&e?badge('日完整 · 曲线缺1点','warn'):badge('完整')}</td><td><button class="text-button" data-usage-detail="${d.id}">明细</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">没有匹配的数据</td></tr>'}</tbody></table></div>${pager(list.length)}`}
function intervalValues(d){const u=usage(d),values=Array(48).fill(0);for(const [period,total] of [['peak',u.peak],['valley',u.valley]]){const indexes=Array.from({length:48},(_,i)=>i).filter(i=>(i>=16&&i<42)===(period==='peak')),weights=indexes.map(i=>1+Math.sin(i*.6+d.index)*.18),sum=weights.reduce((a,b)=>a+b,0);let used=0;indexes.forEach((idx,k)=>{const cents=k===indexes.length-1?Math.round(total*100)-used:Math.round(total*100*weights[k]/sum);used+=cents;values[idx]=cents/100})}return values}
function usageDetail(id){const d=devices.find(d=>d.id===id);if(!d)return;const e=d.type==='electric',u=usage(d),end=reading(d),start=round(end-u.total);const summary=`<div class="detail-grid"><div><span>设备 / 日期</span><b>${d.id} · ${state.date}</b></div><div><span>当日${e?'用电':'用水'}量</span><b>${fmt(u.total)+' '+(e?'kWh':'m³')}</b></div></div>`;let rows='';if(e){let cumulative=start;rows=intervalValues(d).map((v,i)=>{const from=String(Math.floor(i/2)).padStart(2,'0')+':'+(i%2?'30':'00'),to=i===47?'24:00':String(Math.floor((i+1)/2)).padStart(2,'0')+':'+((i+1)%2?'30':'00'),before=cumulative;cumulative=round(cumulative+v);const gap=d.index%41===3&&(i===20||i===21);return `<tr><td class="mono">${from}–${to}</td><td>${badge(i>=16&&i<42?'峰时':'谷时',i>=16&&i<42?'blue':'')}</td><td class="number">${gap?'—':fmt(before)}</td><td class="number">${gap?'—':fmt(cumulative)}</td><td class="number">${gap?'—':fmt(v)}</td><td>${badge(gap?'边界点缺失':'完整',gap?'warn':'')}</td></tr>`}).join('')}else rows=[['00:00',start],['24:00',end]].map(([time,value])=>`<tr><td>${time}</td><td class="number">${fmt(value)}</td><td>${badge('有效读数')}</td></tr>`).join('');modal(e?'半小时用电明细':'每日用水明细',summary+`<div class="note-bar soft">${ico('info')}${e?'用量 = 区间末累计读数 − 区间初累计读数。存在缺失时，不用0替代。':'日用水量 = 24:00读数 − 00:00读数。每天00:00采集一次，日末读数与下一天日初共用同一次采集；失败后最多重试3次。'}</div><div class="table-wrap"><table class="compact"><thead>${e?'<tr><th>用量区间</th><th>时段</th><th>起始读数</th><th>结束读数</th><th>用量 (kWh)</th><th>质量</th></tr>':'<tr><th>计划采集点</th><th>累计读数 (m³)</th><th>质量</th></tr>'}</thead><tbody>${rows}</tbody></table></div>`,btn('关闭','data-close'),true)}
const scopes={'meter.read':'设备查询','electricity.read':'用电量查询','water.read':'用水量查询'};
function appsPage(){return header('第三方应用','为对接系统分配独立凭证，按应用管理接口与设备访问范围。',btn('接口说明','data-action="api-docs"',false,'list')+btn('新增应用','data-action="add-app"',true,'plus'),'APPLICATION ACCESS')+`<section class="panel"><div class="panel-head"><div><div class="panel-title">应用列表</div><div class="panel-subtitle">${data.apps.length} 个应用 · ${data.apps.filter(a=>a.enabled).length} 个已启用</div></div>${badge('应用独立授权','blue')}</div><div class="table-wrap"><table><thead><tr><th>应用名称 / appKey</th><th>appSecret</th><th>接口权限</th><th>数据范围 / IP白名单</th><th>状态</th><th>操作</th></tr></thead><tbody>${data.apps.map(a=>`<tr><td><b style="font-weight:500">${esc(a.name)}</b><span class="subtext mono">${esc(a.key)}</span></td><td class="mono">••••••••${a.last4}<span class="subtext">仅创建或重置时显示一次</span></td><td style="white-space:normal;max-width:210px">${a.scopes.slice(0,3).map(s=>`<span class="scope-tag">${scopes[s]}</span>`).join('')}${a.scopes.length>3?`<span class="subtext">另有 ${a.scopes.length-3} 项权限</span>`:''}</td><td>${a.building==='全部位置'?'全部楼栋':esc(a.building)}<span class="subtext mono">${esc(a.ip||'IP不限制')}</span></td><td>${badge(a.enabled?'启用':'停用',a.enabled?'':'neutral')}</td><td><div class="inline-actions"><button class="text-button" data-app-edit="${a.id}">配置</button><button class="text-button" data-app-toggle="${a.id}">${a.enabled?'停用':'启用'}</button><button class="text-button" data-app-log="${a.id}">日志</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无应用，点击新增应用开始配置</td></tr>'}</tbody></table></div></section><div class="note-bar soft" style="margin-top:18px">${ico('info')}应用仅开放设备查询、用电量查询和用水量查询；停用后保留历史记录。原型凭证仅用于演示。</div>`}
function alarmsPage(){return header('告警中心','集中处理设备离线、设备采集缺失或失败，确认后保留处理记录。',btn('刷新','data-action="refresh"',false,'refresh'),'ALERT CENTER')+`<div class="section-tabs">${[['all','全部告警'],['open','待处理'],['ack','已确认']].map(([v,label])=>`<button data-alarm-tab="${v}" class="${state.status===v?'selected':''}">${label}${v==='open'?' · '+data.alarms.filter(a=>a.status==='open').length:''}</button>`).join('')}</div><section class="panel"><div id="table-area">${alarmsTable()}</div></section>`}

function alarmsTable(){const list=data.alarms.filter(a=>state.status==='all'||a.status===state.status);return `<div class="table-wrap"><table><thead><tr><th>告警内容</th><th>设备</th><th>级别</th><th>发生时间</th><th>处理状态</th><th>确认人</th><th>操作</th></tr></thead><tbody>${pageRows(list).map(a=>`<tr><td>${esc(a.title)}<span class="subtext">${esc(a.id)}</span></td><td class="mono">${esc(a.deviceId)}</td><td>${badge(a.level==='warning'?'提醒':'提示',a.level==='warning'?'warn':'blue')}</td><td class="mono">${esc(a.at)}</td><td>${badge(a.status==='ack'?'已确认':'待处理',a.status==='ack'?'blue':'warn')}</td><td>${a.status==='ack'?esc(a.confirmedBy||'历史未记录'):'—'}${a.status==='ack'&&a.confirmedAt?`<span class="subtext mono">${esc(a.confirmedAt)}</span>`:''}</td><td><button class="text-button" data-alarm-detail="${esc(a.id)}">${a.status==='open'?'详情 / 确认':'详情'}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">当前分类没有告警</td></tr>'}</tbody></table></div>${pager(list.length)}`}

function integrationPage(){const n=data.integration;return header('采集服务对接','业务平台通过解析服务下发任务、同步读数，统一管理对接配置。',btn('编辑配置','data-action="edit-integration"',true,'link'),'SERVICE INTEGRATION')+`<div class="note-bar soft">${ico('info')}以下为演示连接状态；本原型不探测、不请求配置地址，也不向任何设备发送指令。</div><div class="integration-grid"><section class="panel integration-card"><div style="display:flex;justify-content:space-between;align-items:center"><h3>${esc(n.name)}</h3>${badge(n.enabled?'演示 · 正常':'已停用',n.enabled?'':'neutral')}</div>${[['解析服务地址',n.url],['对接凭证',n.tokenSet?'已填写（演示，不保存明文）':'待正式配置'],['设备接入','电表 / 水表'],['设备操作','主动抄表 / 电表断电 / 电表通电'],['业务结果同步','任务状态 / 累计读数 / 设备状态']].map(([k,v])=>`<div class="definition"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<div style="margin-top:20px">${btn('模拟连接检查','data-action="check-integration"',false,'refresh')}</div></section><section class="panel integration-card"><h3>服务职责</h3><div class="definition"><span>业务平台</span><b>档案 · 计划 · 统计 · 应用接口</b></div><div class="definition"><span>解析程序</span><b>报文解析 · 指令生成 · 应答核验</b></div><div class="definition"><span>采集程序</span><b>设备连接 · 原始收发</b></div><div class="connection-path"><div class="connection-node">业务平台<small>业务管理</small></div><span class="connection-line"></span><div class="connection-node">采集解析<small>设备通信</small></div><span class="connection-line"></span><div class="connection-node">水电表<small>读数与状态</small></div></div><p class="form-note">设备操作仅由后台和定时采集发起。第三方应用只查询已入库的设备与用量数据。</p></section></div>`}

function deviceDetail(id){const d=devices.find(x=>x.id===id);if(!d)return;const r=roomFor(id),e=d.type==='electric';modal('设备详情',`<div class="detail-grid">${[['设备编号',d.id],['设备名称',d.name],['通信地址',d.address],['设备型号',d.model],['位置',devicePosition(d)],['关联房间',r?roomLabel(r):'未关联'],['累计'+(e?'电量':'水量'),fmt(reading(d))+' '+(e?'kWh':'m³')],['在线状态',d.online?'在线':'离线'],[e?'供电状态':'采集周期',e?(d.power==='off'?'已断电':'已通电'):'每天00:00'],['最近成功抄表',d.online?TODAY+' 10:00:02':LAST_DAY+' 18:00:00']].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="detail-title">最近7天${e?'用电':'用水'}趋势</div><div class="trend-chart">${lineChart(d.type,d)}</div><div class="form-note">${e?'峰时08:00–21:00，谷时00:00–08:00、21:00–24:00。通断电需等待实际状态核验。':'每天00:00主动抄表，按自然日统计用水量。'}</div>`,btn('用量明细',`id="detail-usage"`)+btn('立即抄表',`id="detail-read"`,true)+(e?`<button class="btn ${d.power==='off'?'':'danger'}" id="detail-power">${d.power==='off'?'通电':'断电'}</button>`:''),true);$('#detail-usage').onclick=()=>usageDetail(id);$('#detail-read').onclick=()=>operationDialog(id,'read');if(e)$('#detail-power').onclick=()=>operationDialog(id,d.power==='off'?'on':'off')}
function deviceForm(id){const old=devices.find(d=>d.id===id),type=old?.type||state.type,e=type==='electric';modal(old?'编辑设备':'新增'+(e?'电表':'水表'),`<form id="device-form"><div class="form-grid"><label class="field">设备名称 *<input name="name" required maxlength="40" value="${esc(old?.name||'')}"></label><label class="field">设备所在幢号（选填）<select name="building"><option value="">未指定</option>${buildings.slice(1).map(b=>`<option ${b===old?.building?'selected':''}>${b}</option>`).join('')}</select></label><label class="field">安装位置（选填）<input name="location" maxlength="60" value="${esc(old?.location||'')}" placeholder="例如：1F / 配电间01"></label><label class="field">通信地址 *<input name="address" required pattern="${e?'[0-9]{12}':'[0-9a-fA-F]{14}'}" title="${e?'12位数字':'14位HEX'}" value="${esc(old?.address||'')}" ${old?'readonly':''} placeholder="${e?'12位数字，保留前导零':'14位HEX，保留原始地址顺序'}"></label><label class="field full">设备型号 *<input name="model" required maxlength="60" value="${esc(old?.model||(e?'DTSU666 三相智能电表':'LXSG-20 智能远传水表'))}"></label></div><div id="form-error" class="form-error" role="alert"></div><p class="form-note">${old?'通信地址用于识别设备，编辑档案时不修改。':'原型新增设备默认离线，实际连接应由采集解析服务确认。'} 保存仅影响本地演示。</p></form>`,btn('取消','data-close')+btn('保存设备','form="device-form" type="submit"',true));$('#device-form').onsubmit=event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));for(const k in values)values[k]=values[k].trim();values.address=values.address.toUpperCase();const error=$('#form-error');if(!values.name||!values.model||!(e?/^\d{12}$/:/^[0-9A-F]{14}$/).test(values.address)){error.textContent='请填写完整信息，通信地址格式须符合设备类型';return}if(devices.some(d=>d.type===type&&d.address===values.address&&d.id!==old?.id)){error.textContent='该通信地址已存在';return}const index=old?.index||Math.max(...devices.filter(d=>d.type===type).map(d=>d.index))+1,record={...(old||{id:(e?'EM':'WM')+String(index).padStart(6,'0'),index,type,readBase:0,online:false,power:'on',added:true}),...values};if(commit(next=>next.deviceEdits[record.id]=record)){if(old)Object.assign(old,record);else devices.unshift(record);$('.close').click();render();toast('设备档案已保存')}}}
function operationDialog(id,operation){if(!data.integration.enabled){toast('采集服务对接已停用，请先启用配置');return}const d=devices.find(x=>x.id===id);if(!d||(!['read','off','on'].includes(operation))||(d.type==='water'&&operation!=='read'))return;const busy=data.tasks.some(t=>t.deviceId===id&&['queued','sent','verifying','retry_wait'].includes(t.status));if(busy){toast('该设备已有操作正在等待结果');return}if(operation==='off'&&data.tasks.some(t=>t.deviceId===id&&t.status==='unknown')){toast('设备存在结果未确认的控制记录，请先核实实际状态');return}confirmDialog(operation==='read'?'发起主动抄表':operation==='off'?'确认断电':'确认通电',`<div class="detail-grid"><div><span>目标设备</span><b>${d.id} · ${esc(deviceDisplayName(d))}</b></div><div><span>执行操作</span><b>${operationLabel[operation]}${operation==='off'?'（拉闸）':operation==='on'?'（合闸）':''}</b></div></div><div class="note-bar ${operation==='off'?'warn':'soft'}">${ico('info')}${operation==='read'?'将创建一次额外抄表任务，不覆盖定时计划采样点。':operation==='off'?'断电会影响目标房间供电。真实系统需要设备状态核验后才确认成功。':'真实系统需要设备应答并读回通电状态后才确认成功。'}</div><p class="form-note">本次为本地模拟操作，不连接服务器或设备。${d.online?'任务将演示排队、应答和结果状态。':'设备当前离线，将记录离线结果。'}</p>`,()=>{const task=createTask(d,operation,'后台操作');if(!task)return false;toast('演示任务已创建，可在采集与控制记录中查看');if(state.page==='tasks'||state.page==='dashboard')render();return true},operation==='read'?'创建抄表任务':operationLabel[operation])}
function createTask(d,operation,source){const task=makeTask(d,operation,source);return commit(next=>next.tasks.unshift(task))?task:null}
function taskDetail(id){renderTaskDetail(id)}
function randomHex(n){const bytes=new Uint8Array(n);crypto.getRandomValues(bytes);return Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('')}
function appForm(id){const old=data.apps.find(a=>a.id===id);modal(old?'配置第三方应用':'新增第三方应用',`<form id="app-form"><div class="form-grid"><label class="field full">应用名称 *<input name="name" required maxlength="50" value="${esc(old?.name||'')}" placeholder="例如：园区运营管理系统"></label><label class="field">appKey *<input name="key" required pattern="[A-Za-z0-9_\-]{6,40}" maxlength="40" value="${esc(old?.key||'wp_'+randomHex(5))}" ${old?'readonly':''}></label><label class="field">数据范围<select name="building">${buildingOptions(old?.building||'全部位置')}</select></label><label class="field full">IP白名单<input name="ip" value="${esc(old?.ip||'')}" placeholder="IPv4 / CIDR，多个用英文逗号分隔；留空不限制"></label></div><div class="detail-title">接口权限</div><div class="check-grid">${Object.entries(scopes).map(([k,v])=>`<label><input type="checkbox" name="scope" value="${k}" ${(old?.scopes||['meter.read','electricity.read','water.read']).includes(k)?'checked':''}>${v}</label>`).join('')}</div><div class="form-error" id="form-error" role="alert"></div><p class="form-note">仅允许访问所选楼栋中的设备。密钥仅创建或重置时显示一次，演示数据不具备真实接口权限。</p>${old?`<button type="button" class="text-button warn" id="reset-app-secret">重置此应用密钥</button>`:''}</form>`,btn('取消','data-close')+btn('保存应用','form="app-form" type="submit"',true));if(old)$('#reset-app-secret').onclick=()=>resetAppSecret(old.id);$('#app-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),v={name:String(fd.get('name')).trim(),key:String(fd.get('key')).trim(),building:String(fd.get('building')),ip:String(fd.get('ip')).trim(),scopes:fd.getAll('scope').filter(k=>Object.hasOwn(scopes,k))};const fail=text=>$('#form-error').textContent=text;if(!v.name||!/^[A-Za-z0-9_-]{6,40}$/.test(v.key))return fail('请填写应用名称和6–40位字母、数字或下划线appKey');if(data.apps.some(a=>a.key===v.key&&a.id!==old?.id))return fail('appKey已存在');if(!v.scopes.length)return fail('请至少选择一项接口权限');if(v.ip&&!v.ip.split(',').every(validCIDR))return fail('IP白名单请填写有效IPv4或CIDR，例如10.10.0.0/16');const secret=old?null:randomHex(24),app={...(old||{id:'APP'+Date.now().toString(36).toUpperCase(),enabled:true,last4:secret.slice(-4),created:nowText(),calls:0}),...v};if(commit(next=>{if(old)next.apps=next.apps.map(a=>a.id===old.id?app:a);else next.apps.push(app)})){render();if(secret)showSecret(app,secret);else{$('.close').click();toast('应用配置已保存')}}}}
function validCIDR(raw){const [ip,prefix,...rest]=raw.trim().split('/'),parts=ip.split('.');return rest.length===0&&parts.length===4&&parts.every(p=>/^\d{1,3}$/.test(p)&&+p<=255)&&(prefix===undefined||/^\d{1,2}$/.test(prefix)&&+prefix<=32)}
function showSecret(app,secret){modal('应用凭证已生成',`<div class="note-bar warn">${ico('info')}appSecret只在本次显示。关闭后无法再次查看，只能重置。</div><div class="secret-box">appKey<code>${esc(app.key)}</code>appSecret<code id="new-secret">${secret}</code></div><p class="form-note">请复制到演示接入记录中。当前密钥仅为原型随机示例，未对接认证服务，也不会保存明文。</p>`,btn('复制凭证','id="copy-secret"')+btn('已保存，关闭','data-close',true));$('#copy-secret').onclick=()=>copyText('appKey: '+app.key+'\nappSecret: '+secret)}
function resetAppSecret(id){const app=data.apps.find(a=>a.id===id);if(!app)return;confirmDialog('重置应用密钥',`<p>应用：${esc(app.name)}</p><p class="form-note">正式系统中，重置会使旧凭证及相关令牌失效。原型将生成新的演示密钥，关闭后无法再次查看。</p>`,()=>{const secret=randomHex(24);if(!commit(next=>{next.apps.find(a=>a.id===id).last4=secret.slice(-4)}))return false;render();showSecret(app,secret);return false},'重置密钥')}
function appLogs(id){const a=data.apps.find(a=>a.id===id);modal('应用调用日志',`<div class="detail-grid"><div><span>应用名称</span><b>${esc(a.name)}</b></div><div><span>历史调用量（演示）</span><b>${fmt(a.calls,0)} 次</b></div></div><div class="table-wrap"><table class="compact"><thead><tr><th>时间</th><th>接口</th><th>状态</th><th>耗时</th></tr></thead><tbody>${[['10:11:02','GET /meters','200','24'],['10:10:59','GET /meters/{id}/electricity','200','38'],['10:09:00','GET /meters/{id}/water','200','16']].map(([t,url,s,ms])=>`<tr><td class="mono">${TODAY} ${t}</td><td class="mono">${url}</td><td>${badge(s)}</td><td>${ms} ms</td></tr>`).join('')}</tbody></table></div><p class="form-note">示例日志用于页面确认，不代表真实API调用；不展示凭证或令牌。</p>`,btn('关闭','data-close'),true)}
function apiDocs(){modal('开放接口说明',`<p class="form-note">第三方应用仅提供三类查询，数据来自业务平台已保存的设备档案和用量记录，不触发设备采集或控制。以下为拟定接口，原型尚未提供HTTP服务。</p><div class="endpoint"><b>POST</b> /oauth2/token <span class="subtext">使用应用凭证换取查询令牌</span></div>${[['GET','/openapi/v1/meters','查询授权范围内的设备列表'],['GET','/openapi/v1/meters/{id}','查询设备信息与在线状态'],['GET','/openapi/v1/meters/{id}/electricity','查询电表用电量、峰谷用电量与历史记录'],['GET','/openapi/v1/meters/{id}/water','查询水表每日用水量与历史记录']].map(([m,p,desc])=>`<div class="endpoint"><b>${m}</b> ${p}<span class="subtext">${desc}</span></div>`).join('')}<div class="note-bar soft" style="margin-top:16px">${ico('info')}应用权限只有设备查询、用电量查询、用水量查询。查询不会触发抄表，也不提供设备控制或任务操作接口。</div>`,btn('关闭','data-close'),true)}
function alarmDetail(id){const a=data.alarms.find(a=>a.id===id);if(!a)return;modal('告警详情',`<div class="detail-grid">${[['告警编号',a.id],['目标设备',a.deviceId],['告警内容',a.title],['发生时间',a.at],['当前状态',a.status==='ack'?'已确认':'待处理'],['确认人',a.status==='ack'?(a.confirmedBy||'历史未记录'):'—'],['确认时间',a.status==='ack'?(a.confirmedAt||'历史未记录'):'—']].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="note-bar ${a.status==='ack'?'soft':'warn'}">${ico('info')}${esc(a.reason)}</div><p class="form-note">确认表示已经知晓告警，不改变设备在线状态或采集结果。确认时自动记录当前操作人和确认时间。</p>`,btn('关闭','data-close')+(a.status==='open'?btn('确认告警','id="ack-alarm"',true):''));if(a.status==='open')$('#ack-alarm').onclick=()=>{if(commit(next=>{const alarm=next.alarms.find(x=>x.id===id);if(alarm.status!=='open')return;Object.assign(alarm,{status:'ack',confirmedById:currentOperator.id,confirmedBy:currentOperator.name,confirmedAt:nowText()});})){$('.close').click();render();toast('告警已确认，已记录确认人和确认时间')}}}

function integrationForm(){const n=data.integration;modal('编辑采集服务对接',`<form id="integration-form"><div class="form-grid"><label class="field full">服务名称 *<input name="name" required value="${esc(n.name)}" maxlength="60"></label><label class="field full">解析服务地址 *<input name="url" required type="url" value="${esc(n.url)}" placeholder="http://127.0.0.1:18082"></label><label class="field full">内部对接令牌<input name="token" type="password" autocomplete="new-password" placeholder="原型请勿填写生产凭证；内容不会保存"></label><label class="field">对接状态<select name="enabled"><option value="true" ${n.enabled?'selected':''}>启用</option><option value="false" ${!n.enabled?'selected':''}>停用</option></select></label></div><p class="form-note">此处仅保存演示服务名称和地址，不进行网络请求；令牌仅记录“已填写”状态，不保存内容。</p><div class="form-error" id="form-error" role="alert"></div></form>`,btn('取消','data-close')+btn('保存配置','form="integration-form" type="submit"',true));$('#integration-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));let url;try{url=new URL(v.url);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error()}catch{$('#form-error').textContent='请输入不含用户名密码的HTTP或HTTPS地址';return}if(commit(next=>next.integration={name:v.name.trim(),url:v.url.trim(),enabled:v.enabled==='true',tokenSet:!!v.token||n.tokenSet})){$('.close').click();render();toast('演示对接配置已保存')}}}
function copyText(text){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('已复制')).catch(()=>fallbackCopy(text))}else fallbackCopy(text)}
function fallbackCopy(text){const box=document.createElement('textarea');box.value=text;box.style.cssText='position:fixed;left:-9999px';document.body.appendChild(box);box.select();let copied=false;try{copied=document.execCommand('copy')}catch{}box.remove();toast(copied?'已复制':'浏览器不允许自动复制，请选中文本手动复制')}
function exportRows(name,headers,rows){const cell=v=>{const s=String(v??'');return '"'+(/^[=+\-@\t\r]/.test(s)?"'":'')+s.replaceAll('"','""')+'"'},blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'_'+state.date+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`已导出${rows.length}条演示记录`)}
function exportUsage(){const e=state.type==='electric',list=filtered();exportRows(e?'电量统计':'水量统计',['日期','设备编号','设备自身名称','显示名称','关联房间','安装位置',...(e?['峰时kWh','谷时kWh','总用电kWh','质量']:['日初00:00读数m3','日末24:00读数m3','用水量m3','质量'])],list.map(d=>{const u=usage(d),end=reading(d),room=roomFor(d.id);return[state.date,d.id,d.name,deviceDisplayName(d),room?roomLabel(room):'未关联房间',devicePosition(d),...(e?[u.peak,u.valley,u.total,d.index%41===3?'日完整，曲线缺1点':'完整']:[round(end-u.total),end,u.total,'完整'])]}))}
function bindPage(){$('#task-type')?.addEventListener('change',e=>{state.taskType=e.target.value;state.pageNo=1;refreshTable()});if(state.page==='rooms')bindRooms();$('#search')?.addEventListener('input',e=>{state.search=e.target.value;state.pageNo=1;refreshTable()});$('#building')?.addEventListener('change',e=>{state.building=e.target.value;state.pageNo=1;refreshTable()});$('#status')?.addEventListener('change',e=>{state.status=e.target.value;state.pageNo=1;refreshTable()});$('#task-status')?.addEventListener('change',e=>{state.status=e.target.value;state.pageNo=1;refreshTable()});$('#task-operation')?.addEventListener('change',e=>{state.taskOperation=e.target.value;state.pageNo=1;refreshTable()});$('#reset')?.addEventListener('click',()=>{Object.assign(state,{search:'',building:'全部位置',status:'all',taskOperation:'all',taskType:'all',pageNo:1});render()});$('#date')?.addEventListener('change',e=>{if(e.target.value<'2026-09-01'||e.target.value>LAST_DAY){toast('请选择模拟数据日期范围内的日期');e.target.value=state.date;return}state.date=e.target.value;render()});}
function refreshTable(){const renderers={electric:deviceTable,water:deviceTable,tasks:tasksTable,usage:usageTable,alarms:alarmsTable};if($('#table-area')&&renderers[state.page])$('#table-area').innerHTML=renderers[state.page]()}
document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=ico(n.dataset.icon));
document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el||el.disabled)return;if(el.dataset.page){event.preventDefault();navigate(el.dataset.page);return}if(el.dataset.nav){navigate(el.dataset.nav);return}if(el.dataset.goto){state.pageNo=+el.dataset.goto;refreshTable();return}if(el.dataset.deviceDetail){deviceDetail(el.dataset.deviceDetail);return}if(el.dataset.detail){deviceDetail(el.dataset.detail);return}if(el.dataset.editDevice){deviceForm(el.dataset.editDevice);return}if(el.dataset.poll){operationDialog(el.dataset.poll,'read');return}if(el.dataset.taskDetail){taskDetail(el.dataset.taskDetail);return}if(el.dataset.usageDetail){usageDetail(el.dataset.usageDetail);return}if(el.dataset.chartType){state.type=el.dataset.chartType;render();return}if(el.dataset.usageType){state.type=el.dataset.usageType;state.pageNo=1;state.search='';render();return}if(el.dataset.planEdit){planForm(el.dataset.planEdit);return}if(el.dataset.planToggle){if(commit(next=>{const p=next.plans.find(p=>p.id===el.dataset.planToggle);p.enabled=!p.enabled})){render();toast('计划状态已更新')}return}if(el.dataset.planRun){runPlan(el.dataset.planRun);return}if(el.dataset.appEdit){appForm(el.dataset.appEdit);return}if(el.dataset.appToggle){const a=data.apps.find(a=>a.id===el.dataset.appToggle);confirmDialog(a.enabled?'停用应用':'启用应用',`<p>${esc(a.name)}</p><p class="form-note">${a.enabled?'正式系统停用后，应用现有令牌也应失效；历史操作记录保留。':'启用后按已配置的接口权限和数据范围提供访问。'}</p>`,()=>{if(!commit(next=>{const app=next.apps.find(x=>x.id===a.id);app.enabled=!app.enabled}))return false;render();toast('应用状态已更新')});return}if(el.dataset.appLog){appLogs(el.dataset.appLog);return}if(el.dataset.alarmTab){state.status=el.dataset.alarmTab;state.pageNo=1;render();return}if(el.dataset.alarmDetail){alarmDetail(el.dataset.alarmDetail);return}const actions={'add-device':()=>deviceForm(),'add-plan':()=>planForm(),'add-app':()=>appForm(),'api-docs':apiDocs,'edit-integration':integrationForm,'check-integration':()=>toast(data.integration.enabled?'模拟检查通过；未发起真实网络请求':'对接配置已停用，未发起连接检查'),refresh:()=>{render();toast('演示数据已刷新')},'export-usage':exportUsage,'export-dashboard':()=>{const e=totals('electric'),w=totals('water');exportRows('园区日报',['日期','日用电kWh','峰时kWh','谷时kWh','日用水m3'],[[state.date,round(e.total),round(e.peak),round(e.valley),round(w.total)]])},'export-devices':()=>exportRows('设备档案',['设备编号','设备自身名称','显示名称','关联房间','地址','型号','在线状态'],filtered().map(d=>[d.id,d.name,deviceDisplayName(d),roomFor(d.id)?roomLabel(roomFor(d.id)):'未关联',d.address,d.model,d.online?'在线':'离线'])),'export-tasks':()=>exportRows('操作记录',['任务','设备','设备类型','动作','来源','创建时间','成功时间','结果'],taskList().map(t=>[t.id,t.deviceId,taskMeterLabel(t),taskOperationName(t),t.source,traceTime(t.createdAt),t.status==='success'?traceTime(t.successAt):'',taskLabels[t.status]?.[0]||t.status]))};if(actions[el.dataset.action])actions[el.dataset.action]();});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
window.addEventListener('beforeunload',()=>clearInterval(simulationTimer));
initializeTaskRecords();
const simulationTimer=setInterval(refreshTaskSimulation,450);
navigate(location.hash.slice(1)||'rooms');
